//! Cross-language golden fixtures for the depth/normal prior codecs.
//!
//! The four files under `crates/brush-dataset/testdata/` are the **shared**
//! half of plan test T18: the Rust tests here and `test_prior_io.py` on the
//! Python side read the *same bytes* against the *same literal tables*. If the
//! two codecs ever drift, one side stops matching the table and the fixture
//! says which.
//!
//! Fixtures and tables come from WS-P's `make_prior_fixtures.py`, generated by
//! the real `prior_io.py` codec rather than written by hand; the full
//! per-pixel tables and the SHA-256 of each file are in `testdata/README.md`.
//!
//! **Every table below is a list of `f32::to_bits` values, not floats, and that
//! is load-bearing rather than fastidious.** Writing an expected value as an
//! algebraically-equivalent literal gives a *different* f32: the codec's pinned
//! `(c as f32) / 255.0 * 2.0 - 1.0` yields `0x3C40C100` at code 129 while
//! `3.0 / 255.0` yields `0x3C40C0C1` -- 5.87e-8 apart, because the trailing
//! `- 1.0` cancels about six decimal digits near zero. Codes 64, 127 and 129
//! all drift like that. A test written against the "obvious" literal fails
//! against correct code (measured, not assumed -- see
//! `normal_png_signed_anchors_bit_exact`).
//!
//! Regenerating the fixtures must reproduce these tables byte for byte; a
//! fixture change that moves a table is a codec change and needs the plan's
//! section 3 decisions revisited.

/// Golden fixture geometry: 3 rows x 4 columns, deliberately non-square so a
/// transposed size is a detectable error.
pub(crate) const GOLDEN_W: usize = 4;
pub(crate) const GOLDEN_H: usize = 3;

// ---------------------------------------------------------------------------
// Part B: quantized PNG priors
// ---------------------------------------------------------------------------

/// 3x4 uint16 PNG, depth in millimetres.
/// SHA-256 `99c951a9d4bf4504115c2fd160f82e0c7a42f18b050ce117cea43d406a4ac587`.
pub(crate) const GOLDEN_DEPTH_U16_PNG: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/testdata/golden_depth_u16.png"
));

/// The millimetre codes stored in [`GOLDEN_DEPTH_U16_PNG`], row-major.
///
/// Covers the sentinel (0), the smallest representable depth (1 mm), the
/// half-to-even rounding neighbourhood (499/500 -- plan D6), a real scene depth
/// (905 mm, the measured playroom minimum), a power-of-two code (32768) and the
/// u16 ceiling (65534/65535, which stays *valid* per D6).
#[rustfmt::skip]
pub(crate) const GOLDEN_DEPTH_MM: [u16; 12] = [
    0,    1,     499,   500,
    1500, 65535, 2,     1000,
    905,  32768, 65534, 12345,
];

/// Expected decode of [`GOLDEN_DEPTH_U16_PNG`] as metres, `f32::to_bits`.
///
/// Contract: `(mm as f32) / 1000.0` (plan D7; `gauss-surf` `render_io.py:161`).
#[rustfmt::skip]
pub(crate) const GOLDEN_DEPTH_METRES_BITS: [u32; 12] = [
    0x0000_0000, 0x3A83_126F, 0x3EFF_7CEE, 0x3F00_0000, // 0.0,   0.001,  0.499,  0.5
    0x3FC0_0000, 0x4283_11EC, 0x3B03_126F, 0x3F80_0000, // 1.5,   65.535, 0.002,  1.0
    0x3F67_AE14, 0x4203_126F, 0x4283_1168, 0x4145_851F, // 0.905, 32.768, 65.534, 12.345
];

/// 3x4 RGB8 PNG of quantized normals.
/// SHA-256 `815cfbea39bb6392bff5b779e6d944fffa28ec6ae6538a74f9863cd60b47dad1`.
pub(crate) const GOLDEN_NORMAL_U8_PNG: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/testdata/golden_normal_u8.png"
));

/// The uint8 codes stored in [`GOLDEN_NORMAL_U8_PNG`], row-major, interleaved.
#[rustfmt::skip]
pub(crate) const GOLDEN_NORMAL_CODES: [u8; 36] = [
    0, 0, 0,       255, 255, 255,  128, 128, 128,  127, 128, 129,
    0, 128, 255,   129, 127, 128,  64, 192, 32,    1, 254, 128,
    128, 0, 128,   255, 128, 0,    100, 150, 200,  127, 127, 127,
];

/// Expected decode of [`GOLDEN_NORMAL_U8_PNG`], `f32::to_bits`.
///
/// Contract: `(c as f32) / 255.0 * 2.0 - 1.0`, **except code 128 -> exact 0.0**
/// (plan D1/D7; `gauss-surf` `normals_encoding.py:52-53`). The 128 override is
/// what makes `(0,0,0)` invalid round-trip, and it is the reason 127 and 129
/// are not symmetric about zero.
#[rustfmt::skip]
pub(crate) const GOLDEN_NORMAL_UNIT_BITS: [u32; 36] = [
    0xBF80_0000, 0xBF80_0000, 0xBF80_0000, // (0,0,0)       -> (-1, -1, -1)
    0x3F80_0000, 0x3F80_0000, 0x3F80_0000, // (255,255,255) -> (+1, +1, +1)
    0x0000_0000, 0x0000_0000, 0x0000_0000, // (128,128,128) -> invalid (0,0,0)
    0xBB80_8080, 0x0000_0000, 0x3C40_C100, // (127,128,129) -> the asymmetry
    0xBF80_0000, 0x0000_0000, 0x3F80_0000, // (0,128,255)
    0x3C40_C100, 0xBB80_8080, 0x0000_0000, // (129,127,128)
    0xBEFE_FEFE, 0x3F01_8182, 0xBF3F_BFC0, // (64,192,32)
    0xBF7D_FDFE, 0x3F7D_FDFE, 0x0000_0000, // (1,254,128)
    0x0000_0000, 0xBF80_0000, 0x0000_0000, // (128,0,128)   -> (0, -1, 0)
    0x3F80_0000, 0x0000_0000, 0xBF80_0000, // (255,128,0)
    0xBE5C_DCDC, 0x3E34_B4B8, 0x3F11_9192, // (100,150,200)
    0xBB80_8080, 0xBB80_8080, 0xBB80_8080, // (127,127,127)
];

/// Flat index of the all-128 (invalid) pixel in [`GOLDEN_NORMAL_CODES`].
pub(crate) const GOLDEN_NORMAL_INVALID_PIXEL: usize = 2;

/// Flat index of a pixel with **one** 128 component and two ordinary ones.
///
/// `(128, 0, 128)` decodes to `(0, -1, 0)`: a perfectly good toward-camera
/// normal. The override is per *component*, so a single 128 must not
/// invalidate the pixel.
pub(crate) const GOLDEN_NORMAL_PARTIAL_128_PIXEL: usize = 8;

// ---------------------------------------------------------------------------
// Part A: lossless Deflate + FloatingPoint-predictor TIFFs
// ---------------------------------------------------------------------------

/// 3x4 float32 TIFF, `compression="deflate", predictor=True` (predictor 3),
/// written by `tifffile` + `imagecodecs`.
/// SHA-256 `84557ed8febff8f243c7d333995adfd617322c7a65e22830b88d16a01313edcb`.
///
/// The Rust `tiff` encoder cannot emit predictor 3 (`encoder/mod.rs:38`) even
/// though the decoder reads it, so a checked-in fixture is the only honest test
/// of the decode path Part A ships -- and Part A is already live: the
/// production prior directories were recompressed to
/// `(compression 32946, predictor 3)` on 2026-08-21.
pub(crate) const PREDICTOR3_DEPTH_TIFF: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/testdata/predictor3_depth.tiff"
));

/// Expected decode of [`PREDICTOR3_DEPTH_TIFF`], `f32::to_bits`.
///
/// Carries `-0.0`, both infinities, a quiet `NaN`, a subnormal and `FLT_MAX`
/// precisely so that any float normalisation on the way through shows up. This
/// is also why the comparison is on bits: `NaN == NaN` is false and
/// `-0.0 == 0.0` is true, so a float compare would be simultaneously too strict
/// and too lax.
#[rustfmt::skip]
pub(crate) const PREDICTOR3_DEPTH_BITS: [u32; 12] = [
    0x0000_0000, 0x8000_0000, 0x3F80_0000, 0xBF80_0000, // +0, -0, 1, -1
    0x006C_E3EE, 0x7F7F_FFFF, 0x7FC0_0000, 0x7F80_0000, // subnormal, FLT_MAX, NaN, +inf
    0xFF80_0000, 0x3F67_AE14, 0x3FB9_6873, 0x4283_11EC, // -inf, 0.905, 1.4485, 65.535
];

/// 3x4x3 float32 TIFF, same compression, with an all-zero (invalid) pixel.
/// SHA-256 `2036e0d28d96132e3fb24079149551cefe01aabab49f6b444daac16f0a18b77c`.
pub(crate) const PREDICTOR3_NORMAL_TIFF: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/testdata/predictor3_normal.tiff"
));

/// Expected decode of [`PREDICTOR3_NORMAL_TIFF`], `f32::to_bits`.
#[rustfmt::skip]
pub(crate) const PREDICTOR3_NORMAL_BITS: [u32; 36] = [
    0x0000_0000, 0x0000_0000, 0xBF80_0000,
    0x0000_0000, 0x0000_0000, 0x0000_0000, // the invalid pixel
    0x3F80_0000, 0x0000_0000, 0x0000_0000,
    0xBF80_0000, 0x0000_0000, 0x0000_0000,
    0x0000_0000, 0x3F80_0000, 0x0000_0000,
    0x0000_0000, 0xBF80_0000, 0x0000_0000,
    0x3F13_CD3A, 0x3F13_CD3A, 0xBF13_CD3A,
    0xBF13_CD3A, 0xBF13_CD3A, 0xBF13_CD3A,
    0x8000_0000, 0x7FC0_0000, 0x7F80_0000, // -0, NaN, +inf
    0xFF80_0000, 0x006C_E3EE, 0x7F7F_FFFF, // -inf, subnormal, FLT_MAX
    0x3B80_8080, 0xBB80_8080, 0xBF7F_FFFF,
    0x3F35_04F3, 0x0000_0000, 0xBF35_04F3,
];

// ---------------------------------------------------------------------------

/// FNV-1a-64 over each fixture's raw bytes, in the order depth-PNG,
/// normal-PNG, depth-TIFF, normal-TIFF.
///
/// The decode tables above pin the fixtures' *content*; this pins their
/// *bytes*. A re-encode that happens to decode identically (a different PNG
/// filter, say) would slip past the tables but leave the Python side reading a
/// file whose SHA-256 no longer matches `testdata/README.md`. Cheaper than
/// pulling a SHA-2 dependency into this crate for one assertion.
pub(crate) const FIXTURE_FNV1A64: [u64; 4] = [
    0x9197_33ce_707d_c817,
    0xd59d_afba_6a2d_b801,
    0xa2d4_902d_9cfa_b19c,
    0x3488_68ab_b1f9_661f,
];

/// FNV-1a-64, so a fixture's bytes can be pinned without a hash dependency.
pub(crate) fn fnv1a64(bytes: &[u8]) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for &byte in bytes {
        hash ^= u64::from(byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The committed fixture bytes are exactly the ones these tables were
    /// generated from, and exactly the ones the Python side reads.
    #[test]
    fn fixture_bytes_are_pinned() {
        let files: [(&str, &[u8]); 4] = [
            ("golden_depth_u16.png", GOLDEN_DEPTH_U16_PNG),
            ("golden_normal_u8.png", GOLDEN_NORMAL_U8_PNG),
            ("predictor3_depth.tiff", PREDICTOR3_DEPTH_TIFF),
            ("predictor3_normal.tiff", PREDICTOR3_NORMAL_TIFF),
        ];
        for (i, (name, bytes)) in files.iter().enumerate() {
            assert_eq!(
                fnv1a64(bytes),
                FIXTURE_FNV1A64[i],
                "{name} is not the committed fixture"
            );
        }

        // Null model: the digest must actually discriminate. One flipped byte
        // in any fixture has to change it.
        for (name, bytes) in &files {
            let mut mutated = bytes.to_vec();
            let last = mutated.len() - 1;
            mutated[last] ^= 0x01;
            assert_ne!(fnv1a64(&mutated), fnv1a64(bytes), "{name}");
        }
    }

    /// The tables must agree with each other on shape, so a half-updated
    /// fixture refresh cannot leave a stale table in place.
    #[test]
    fn tables_are_internally_consistent() {
        assert_eq!(GOLDEN_DEPTH_MM.len(), GOLDEN_W * GOLDEN_H);
        assert_eq!(GOLDEN_DEPTH_METRES_BITS.len(), GOLDEN_W * GOLDEN_H);
        assert_eq!(GOLDEN_NORMAL_CODES.len(), GOLDEN_W * GOLDEN_H * 3);
        assert_eq!(GOLDEN_NORMAL_UNIT_BITS.len(), GOLDEN_W * GOLDEN_H * 3);
        assert_eq!(PREDICTOR3_DEPTH_BITS.len(), GOLDEN_W * GOLDEN_H);
        assert_eq!(PREDICTOR3_NORMAL_BITS.len(), GOLDEN_W * GOLDEN_H * 3);

        let base = GOLDEN_NORMAL_INVALID_PIXEL * 3;
        assert_eq!(&GOLDEN_NORMAL_CODES[base..base + 3], &[128_u8, 128, 128]);
        let base = GOLDEN_NORMAL_PARTIAL_128_PIXEL * 3;
        assert_eq!(&GOLDEN_NORMAL_CODES[base..base + 3], &[128_u8, 0, 128]);
    }
}
